/* @ts-nocheck */
import React, { useRef } from 'react';
import { useTheme } from '../shared/use-theme.js';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { useTouchRipple } from '../shared/use-touch-ripple.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { FabClasses } from '../../shared/classes/FabClasses.js';
import { FabColors } from '../../shared/colors/FabColors.js';
import Glass from './Glass.tsx';

const Fab = (props) => {
  const {
    component = 'a',
    className,
    colors: colorsProp,
    href,
    text,
    textPosition = 'after',
    icon,

    ios,
    material,

    // Children
    children,

    ref,

    // Rest
    ...rest
  } = props;

  const rippleElRef = useRef(null);

  const Component = component;

  const attrs = {
    ...rest,
  };

  const theme = useTheme({ ios, material });
  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  useTouchRipple(rippleElRef, theme === 'material');

  const colors = FabColors(colorsProp, dark);

  const c = themeClasses(FabClasses(props, colors, dark), className);

  return (
    <Glass
      component={Component}
      className={text ? c.base.withText : c.base.iconOnly}
      href={href}
      ref={(el) => {
        rippleElRef.current = el;
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
      }}
      role="button"
      tabIndex="0"
      {...attrs}
    >
      {text && textPosition === 'before' && (
        <span className={c.text}>{text}</span>
      )}
      {icon && <span className={c.icon}>{icon}</span>}
      {text && textPosition === 'after' && (
        <span className={c.text}>{text}</span>
      )}
      {children}
    </Glass>
  );
};

Fab.displayName = 'Fab';

export default Fab;

/* @ts-nocheck */
import React, { useEffect, useRef, useContext } from 'react';
import { GlassClasses } from '../../shared/classes/GlassClasses.js';
import { GlassColors } from '../../shared/colors/GlassColors.js';
import { useThemeClasses } from '../shared/use-theme-classes.js';
import { useTheme } from '../shared/use-theme.js';
import { useDarkClasses } from '../shared/use-dark-classes.js';
import { useIosHighlight } from '../../shared/use-ios-highlight.js';
import { CapacitorContext } from '../shared/CapacitorContext.js';

const Glass = (props) => {
  const {
    component = 'div',
    colors: colorsProp,
    className,
    highlight = true,

    ios,
    material,

    // Children
    children,

    ref,

    // Rest
    ...rest
  } = props;

  const elRef = useRef(null);

  const Component = component;

  const attrs = {
    ...rest,
  };

  const theme = useTheme();

  const themeClasses = useThemeClasses({ ios, material });
  const dark = useDarkClasses();

  const colors = GlassColors(colorsProp, dark);

  const { touchHighlight } = useContext(CapacitorContext);

  const highlightData = useRef({});
  const { attachEvents, detachEvents } = useIosHighlight({
    getEl: () => elRef.current,
    enabled: highlight && theme === 'ios' && touchHighlight,
    data: highlightData.current,
  });

  const c = themeClasses(GlassClasses(props, colors), className);

  useEffect(() => {
    attachEvents();
    return () => detachEvents();
  });

  return (
    <Component
      ref={(el) => {
        if (ref && typeof ref === 'function') ref(el);
        else if (ref) ref.current = el;
        elRef.current = el;
      }}
      className={c.base}
      {...attrs}
    >
      {children}
    </Component>
  );
};

Glass.displayName = 'Glass';

export default Glass;
